		setToolTipText("");
		setBackground(BreakpointTimelinePanel.BG_COLOR);

		addComponentListener(new _Anon_ComponentAdapter_1());

		addMouseListener(new _Anon_MouseAdapter_2());

		addMouseWheelListener(new _Anon_MouseAdapter_3());

		addMouseMotionListener(new _Anon_MouseAdapter_4());
	}

	void toggleGridOrColumn() {
		singleColumn = !singleColumn;
		calculateGridAndBuildCache();
	}

	void toggleGridOutline() {
		showGridOutline = !showGridOutline;
		repaint();
	}

	private void zoom() {
		Optional<BreakpointTimelinePanel.CachedIndex> start =
			cells.values().stream().filter(s => s.getRect().contains(dragStart)).findFirst();
		if (start.isPresent()) {
			long startSnap = start.get().getStartSnap();

			Optional<BreakpointTimelinePanel.CachedIndex> stop =
				cells.values().stream().filter(s => s.getRect().contains(dragEnd)).findFirst();
			if (stop.isPresent()) {
				long endSnap = stop.get().getStopSnap();

				if (startSnap > endSnap) {
					long temp = startSnap;
					startSnap = endSnap;
					endSnap = temp;
				}

				string zoomName = "Timeline Zoom: %d - %d".formatted(startSnap, endSnap - 1);
				provider.createZoomProvider(zoomName, startSnap, endSnap);
			}
		}
	}

	internal class _Anon_ComponentAdapter_1 : ComponentAdapter
	{

			/* @Override */
			public void componentResized(ComponentEvent e) {
