	internal class _Anon_MouseAdapter_2 : MouseAdapter
	{

			/* @Override */
			public void mouseExited(MouseEvent e) {
				mousePos = null;
				repaint();
			}

			/* @Override */
			public void mousePressed(MouseEvent e) {
				dragStart = e.getPoint();
			}

			/* @Override */
			public void mouseReleased(MouseEvent e) {
				if (dragEnd != null) {
					zoom();
				}
				else {
					click(dragStart);
				}
				dragStart = null;
				dragEnd = null;
				startDragIndex = null;
				endDragIndex = null;
				repaint();
			}
		
	}


	internal class _Anon_MouseAdapter_3 : MouseAdapter
	{


			/* @Override */
			public void mouseWheelMoved(MouseWheelEvent e) {
				int rotation = e.getWheelRotation();
				if (rotation > 0) {
					getTraceManagerService()
							.activateSnap(getTraceManagerService().getCurrentSnap() + 1);
				}
				else {
					getTraceManagerService()
							.activateSnap(getTraceManagerService().getCurrentSnap() - 1);
				}
				repaint();
			}
		
	}


	internal class _Anon_MouseAdapter_4 : MouseAdapter
	{

			/* @Override */
			public void mouseDragged(MouseEvent e) {
				dragEnd = e.getPoint();
				Optional<BreakpointTimelinePanel.CachedIndex> start = cells.values()
						.stream()
						.filter(s => s.getRect().contains(dragStart))
						.findFirst();
				if (start.isPresent()) {
					Optional<BreakpointTimelinePanel.CachedIndex> end = cells.values()
							.stream()
							.filter(s => s.getRect().contains(dragEnd))
							.findFirst();
					if (end.isPresent()) {
						if (start.get().getIndex() < end.get().getIndex()) {
							startDragIndex = start.get();
							endDragIndex = end.get();
						}
						else {
							startDragIndex = end.get();
							endDragIndex = start.get();
						}
					}
				}
				repaint();
			}

			/* @Override */
			public void mouseMoved(MouseEvent e) {
				mousePos = e.getPoint();
				Optional<BreakpointTimelinePanel.CachedIndex> indexSpan =
					cells.values().stream().filter(s => s.getRect().contains(mousePos)).findFirst();
				if (indexSpan.isPresent() && (lastHighlightedIndex != indexSpan.get())) {
					lastHighlightedIndex = indexSpan.get();
					repaint();
				}
			}
		
	}

